"""Harmonic overtone filter for suppressing distortion artifacts in electric guitars."""

from src.models import NoteEvent

# Standard harmonic intervals relative to root note
OCTAVE_INTERVAL = 12  # Octave overtone
FIFTH_INTERVAL = 19  # Octave + Perfect fifth overtone
DOUBLE_OCTAVE_INTERVAL = 24  # Double octave overtone


class HarmonicFilter:
    """Filters spurious harmonic overtones commonly generated by high-gain electric guitar distortion."""

    def __init__(
        self,
        time_tolerance: float = 0.06,
        octave_ratio: float = 0.85,
        fifth_ratio: float = 0.75,
        double_octave_ratio: float = 0.65,
    ) -> None:
        self.time_tolerance = time_tolerance
        self.octave_ratio = octave_ratio
        self.fifth_ratio = fifth_ratio
        self.double_octave_ratio = double_octave_ratio

    def is_overtone(self, root: NoteEvent, candidate: NoteEvent) -> bool:
        """Determine if candidate note is a spurious overtone of the root note."""
        if candidate.pitch <= root.pitch:
            return False

        # Check temporal overlap or close onset
        close_onsets = abs(candidate.start_time - root.start_time) <= self.time_tolerance
        overlaps = max(root.start_time, candidate.start_time) < min(
            root.end_time, candidate.end_time
        )

        if not (close_onsets or overlaps):
            return False

        semitone_diff = candidate.pitch - root.pitch

        # 1st Octave (+12)
        if (
            semitone_diff == OCTAVE_INTERVAL
            and candidate.amplitude <= root.amplitude * self.octave_ratio
        ):
            return True

        # Octave + Fifth (+19)
        if (
            semitone_diff == FIFTH_INTERVAL
            and candidate.amplitude <= root.amplitude * self.fifth_ratio
        ):
            return True

        # 2nd Octave (+24)
        if (
            semitone_diff == DOUBLE_OCTAVE_INTERVAL
            and candidate.amplitude <= root.amplitude * self.double_octave_ratio
        ):
            return True

        return False

    def filter_overtones(self, notes: list[NoteEvent]) -> list[NoteEvent]:
        """Filter out spurious overtone notes, preserving true fundamental pitches."""
        if not notes:
            return []

        # Sort by start_time, then by amplitude descending to prioritize strong fundamentals
        sorted_notes = sorted(notes, key=lambda n: (n.start_time, -n.amplitude, n.pitch))
        surviving_notes: list[NoteEvent] = []

        for candidate in sorted_notes:
            is_spurious = False
            for accepted in surviving_notes:
                if self.is_overtone(accepted, candidate):
                    is_spurious = True
                    break

            if not is_spurious:
                surviving_notes.append(candidate)

        # Return sorted by (start_time, pitch)
        surviving_notes.sort(key=lambda n: (n.start_time, n.pitch))
        return surviving_notes
